def test_sample_gives_log_returns_dated_after_base() -> None:
    returns = log_returns(_sample_prices())
    assert returns.base_date == "2024-03-01"
    assert returns.dates == ("2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08")
    assert returns.tickers == ("AAA", "BBB")
    aaa_growth = (1.01, 1.005, 1.01, 1.02, 1.005)
    bbb_growth = (1.02, 0.98, 0.99, 1.01, 1.005)
    assert returns.values["AAA"] == pytest.approx(
        tuple(math.log(g) for g in aaa_growth), abs=1e-12, rel=0
    )
    assert returns.values["BBB"] == pytest.approx(
        tuple(math.log(g) for g in bbb_growth), abs=1e-12, rel=0
    )


def test_log_returns_are_not_simple_returns() -> None:
    prices = Prices(
        dates=("2024-01-02", "2024-01-03"), tickers=("AAA",), closes={"AAA": (1.0, 2.0)}
    )
    value = log_returns(prices).values["AAA"][0]
    assert value == pytest.approx(0.6931471805599453, abs=1e-12, rel=0)
    assert value != pytest.approx(1.0)


def test_log_returns_sum_to_log_of_total_growth() -> None:
    prices = Prices(
        dates=("d1", "d2", "d3", "d4"), tickers=("AAA",), closes={"AAA": (10.0, 12.0, 9.0, 15.0)}
    )
    assert sum(log_returns(prices).values["AAA"]) == pytest.approx(
        math.log(1.5), abs=1e-12, rel=0
    )


def test_unchanged_close_gives_zero_return() -> None:
    prices = Prices(dates=("d1", "d2"), tickers=("AAA",), closes={"AAA": (7.0, 7.0)})
    assert log_returns(prices).values["AAA"] == (0.0,)

